    input  wire        start,
    input  wire [31:0] src_addr,
    input  wire [31:0] dst_addr,
    input  wire [31:0] wgt_addr,
    input  wire [31:0] bias_addr,
    input  wire [15:0] in_w, in_h, in_c,
    input  wire [15:0] out_w, out_h, out_c,
    input  wire [3:0]  kernel, stride, pad, act_type,
    input  wire [15:0] rq_mult,
    input  wire [4:0]  rq_shift,
    input  wire        depthwise,
    // Codes-per-unit for this layer's output activations, Q8.8. Only used when
    // act_type is SILU: the INT8 code -> real value mapping differs per layer,
    // so the activation cannot be a single fixed table. 0 means "not set",
